import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import kotlinx.coroutines.flow.*

class FakeLocationManager {
    var listener: ((Int) -> Unit)? = null
    fun requestUpdates(l: (Int) -> Unit) { listener = l; println("register") }
    fun removeUpdates() { listener = null; println("remove") }
}

fun locations(m: FakeLocationManager) = callbackFlow {
    m.requestUpdates { trySend(it) }
    awaitClose { m.removeUpdates() }
}

fun main() = runBlocking {
    val m = FakeLocationManager()
    launch { delay(10); listOf(1, 2, 3).forEach { m.listener?.invoke(it) } }
    locations(m).take(2).collect { println("loc $it") }
    println("done")
}

import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    val events = Channel<String>(Channel.BUFFERED)
    events.send("Navigate")
    events.send("Toast")
    val flow = events.receiveAsFlow()
    flow.take(1).collect { println("screen1: $it") }
    val job = launch { flow.collect { println("screen2: $it") } }
    delay(10)
    job.cancel()
}
